 1	// RUN: %dafny /compile:0 "%s" > "%t"
 2	// RUN: %diff "%s.expect" "%t"
 3	
 4	class Benchmark2 {
 5	  method BinarySearch(a: array<int>, key: int) returns (result: int)
 6	    requires forall i, j :: 0 <= i < j < a.Length ==> a[i] <= a[j];
 7	    ensures -1 <= result < a.Length;
 8	    ensures 0 <= result ==> a[result] == key;
 9	    ensures result == -1 ==> forall i :: 0 <= i < a.Length ==> a[i] != key;
10	  {
11	    var low := 0;
12	    var high := a.Length;
13	
14	    while (low < high)
15	      invariant 0 <= low <= high <= a.Length;
16	      invariant forall i :: 0 <= i < low ==> a[i] < key;
17	      invariant forall i :: high <= i < a.Length ==> key < a[i];
18	    {
19	      var mid := low + (high - low) / 2;
20	      var midVal := a[mid];
21	
22	      if (midVal < key) {
23	        low := mid + 1;
24	      } else if (key < midVal) {
25	        high := mid;
26	      } else {
27	        result := mid; // key found
28	        return;
29	      }
30	    }
31	    result := -1;  // key not present
32	  }
33	}
34	
35	method Main() {
36	  var a := new int[5];
37	  a[0] := -4;
38	  a[1] := -2;
39	  a[2] := -2;
40	  a[3] := 0;
41	  a[4] := 25;
42	  TestSearch(a, 4);
43	  TestSearch(a, -8);
44	  TestSearch(a, -2);
45	  TestSearch(a, 0);
46	  TestSearch(a, 23);
47	  TestSearch(a, 25);
48	  TestSearch(a, 27);
49	}
50	
51	method TestSearch(a: array<int>, key: int)
52	  requires forall i, j :: 0 <= i < j < (a.Length) - 1 ==> a[i] <= a[j];
53	{
54	  var b := new Benchmark2;
55	  var r := b.BinarySearch(a, key);
56	  print "Looking for key=", key, ", result=", r, "\n";
57	}
58

